const NAME = /^[A-Za-z0-9_.-]+$/
const UINT = /^[0-9]+$/

export class UserError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

function fail(message) {
  throw new UserError(message, 2)
}

/**
 * Parse the graph text. Returns { names, cost, deps } where `names` holds the
 * declared task names in declaration order, `cost` maps a name to its cost and
 * `deps` maps a name to the array of its distinct dependencies in the order
 * they were first seen.
 */
export function parseGraph(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cost = new Map()
  const deps = new Map()
  const names = []
  // Every name a dep line uses, in input order, so the first undeclared one
  // can be reported.
  const used = []

  const ensure = (name) => {
    if (!deps.has(name)) deps.set(name, [])
    return deps.get(name)
  }

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) fail(`line ${lineNum}: expected task <name> <cost>`)
      const name = words[1]
      const costText = words[2]
      if (!NAME.test(name)) fail(`line ${lineNum}: invalid task name ${name}`)
      if (!UINT.test(costText)) fail(`line ${lineNum}: cost must be a non-negative integer`)
      if (cost.has(name)) fail(`line ${lineNum}: task ${name} is declared twice`)
      cost.set(name, Number(costText))
      names.push(name)
      ensure(name)
    } else if (directive === 'dep') {
      if (words.length < 3) fail(`line ${lineNum}: expected dep <name> <dependency>...`)
      for (let w = 1; w < words.length; w++) {
        if (!NAME.test(words[w])) fail(`line ${lineNum}: invalid task name ${words[w]}`)
      }
      const name = words[1]
      used.push(name)
      const list = ensure(name)
      for (let w = 2; w < words.length; w++) {
        const dep = words[w]
        used.push(dep)
        if (!list.includes(dep)) list.push(dep)
      }
    } else {
      fail(`line ${lineNum}: unknown directive ${directive}`)
    }
  }

  for (const name of used) {
    if (!cost.has(name)) fail(`unknown task ${name}`)
  }

  return { names, cost, deps }
}
