{"file_path":"src/graph.js","content":"/**
 * Analysing a build graph: waves, timings, priorities and the packing
 * simulation.
 */

export function byName(a, b) {
  return a < b ? -1 : a > b ? 1 : 0
}

export function sortedNames(names) {
  return [...names].sort(byName)
}

/**
 * The first cycle a depth-first search finds when it starts from each task in
 * ascending name order and walks each task's dependencies in ascending name
 * order, or null when the graph is acyclic. The cycle runs from the task the
 * search re-entered, through the search stack, back to that task.
 */
export function findCycle(names, deps) {
  const order = new Map() // name -> index on the current stack, when on it
  const done = new Set()
  const sortedDeps = new Map()
  for (const name of names) sortedDeps.set(name, sortedNames(deps.get(name) || []))

  for (const root of sortedNames(names)) {
    if (done.has(root)) continue
    const stack = [root]
    const cursor = [0]
    order.set(root, 0)

    while (stack.length > 0) {
      const node = stack[stack.length - 1]
      const list = sortedDeps.get(node)
      const at = cursor[cursor.length - 1]
      if (at >= list.length) {
        stack.pop()
        cursor.pop()
        order.delete(node)
        done.add(node)
        continue
      }
      cursor[cursor.length - 1] = at + 1
      const dep = list[at]
      if (order.has(dep)) return stack.slice(order.get(dep))
      if (done.has(dep)) continue
      order.set(dep, stack.length)
      stack.push(dep)
      cursor.push(0)
    }
  }
  return null
}

/** The declared tasks in an order where every task follows its dependencies. */
function topological(names, deps) {
  const dependents = new Map()
  const remaining = new Map()
  for (const name of names) {
    dependents.set(name, [])
    remaining.set(name, 0)
  }
  for (const name of names) {
    for (const dep of deps.get(name) || []) {
      dependents.get(dep).push(name)
      remaining.set(name, remaining.get(name) + 1)
    }
  }
  const queue = names.filter((name) => remaining.get(name) === 0)
  const order = []
  for (let i = 0; i < queue.length; i++) {
    const name = queue[i]
    order.push(name)
    for (const next of dependents.get(name)) {
      remaining.set(next, remaining.get(next) - 1)
      if (remaining.get(next) === 0) queue.push(next)
    }
  }
  return { order, dependents }
}

/**
 * Depth (wave), start and finish of every task with unlimited workers.
 */
export function analyse(names, cost, deps) {
  const { order, dependents } = topological(names, deps)
  const depth = new Map()
  const start = new Map()
  const finish = new Map()

  for (const name of order) {
    let d = 0
    let s = 0
    const list = deps.get(name) || []
    for (const dep of list) {
      d = Math.max(d, depth.get(dep) + 1)
      s = Math.max(s, finish.get(dep))
    }
    depth.set(name, d)
    start.set(name, s)
    finish.set(name, s + cost.get(name))
  }

  let total = 0
  for (const f of finish.values()) total = Math.max(total, f)

  // The cost of the longest chain beginning at each task.
  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i]
    let best = 0
    for (const next of dependents.get(name)) best = Math.max(best, priority.get(next))
    priority.set(name, cost.get(name) + best)
  }

  return { depth, start, finish, total, priority, dependents }
}

/**
 * The list-scheduling simulation behind `pack`.
 */
export function pack(names, cost, deps, workerCount) {
  const { priority, dependents } = analyse(names, cost, deps)
  const workers = []
  for (let i = 0; i < workerCount; i++) workers.push({ freeAt: 0, ran: [] })

  const unmet = new Map()
  for (const name of names) unmet.set(name, (deps.get(name) || []).length)

  const ready = names.filter((name) => unmet.get(name) === 0).sort(byName)
  const running = [] // { name, finish }
  const started = new Set()
  let now = 0
  let makespan = 0

  const release = (name) => {
    for (const next of dependents.get(name)) {
      unmet.set(next, unmet.get(next) - 1)
      if (unmet.get(next) === 0) ready.push(next)
    }
  }

  const takeBest = () => {
    let best = 0
    for (let i = 1; i < ready.length; i++) {
      const p = priority.get(ready[i])
      const q = priority.get(ready[best])
      if (p > q || (p === q && byName(ready[i], ready[best]) < 0)) best = i
    }
    const name = ready[best]
    ready.splice(best, 1)
    return name
  }

  while (started.size < names.length) {
    // Everything that has finished by now frees its dependents.
    for (let i = running.length - 1; i >= 0; i--) {
      if (running[i].finish <= now) {
        release(running[i].name)
        running.splice(i, 1)
      }
    }

    let progress = true
    while (progress) {
      progress = false
      if (ready.length === 0) break
      let free = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].freeAt <= now) {
          free = i
          break
        }
      }
      if (free === -1) break

      const name = takeBest()
      const finish = now + cost.get(name)
      workers[free].ran.push({ name, start: now, finish })
      workers[free].freeAt = finish
      started.add(name)
      makespan = Math.max(makespan, finish)
      if (finish <= now) release(name)
      else running.push({ name, finish })
      progress = true
    }

    if (started.size >= names.length) break

    let next = Infinity
    for (const worker of workers) {
      if (worker.freeAt > now) next = Math.min(next, worker.freeAt)
    }
    if (next === Infinity) break
    now = next
  }

  return { workers, makespan }
}
"}

