import { readFileSync } from 'node:fs'
import { parseGraph, UserError } from './parse.js'
import { analyse, findCycle, pack, sortedNames } from './graph.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'

function parseArgs(argv) {
  const args = argv.slice(2)
  if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) {
    return { command: args[0], workers: 0 }
  }
  if (args.length === 2 && args[0] === 'pack') {
    const text = args[1]
    if (!/^[1-9][0-9]*$/.test(text)) {
      throw new UserError('workers must be a positive integer', 2)
    }
    return { command: 'pack', workers: Number(text) }
  }
  throw new UserError(USAGE, 2)
}

function report(args, graph) {
  const { names, cost, deps } = graph
  const out = []

  if (args.command === 'pack') {
    const { workers, makespan } = pack(names, cost, deps, args.workers)
    for (let i = 0; i < workers.length; i++) {
      let line = `worker ${i}:`
      for (const run of workers[i].ran) line += ` ${run.name}@${run.start}-${run.finish}`
      out.push(line)
    }
    out.push(`makespan ${makespan}`)
    return out
  }

  const { depth, start, finish, total } = analyse(names, cost, deps)

  if (args.command === 'waves') {
    const waves = []
    for (const name of sortedNames(names)) {
      const d = depth.get(name)
      while (waves.length <= d) waves.push([])
      waves[d].push(name)
    }
    for (let i = 0; i < waves.length; i++) out.push(`wave ${i}: ${waves[i].join(' ')}`)
  } else {
    for (const name of sortedNames(names)) {
      out.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
    }
  }
  out.push(`total ${total}`)
  return out
}

function main() {
  let args
  try {
    args = parseArgs(process.argv)
    const graph = parseGraph(readFileSync(0, 'utf8'))
    const cycle = findCycle(graph.names, graph.deps)
    if (cycle) {
      throw new UserError(`cycle: ${[...cycle, cycle[0]].join(' -> ')}`, 3)
    }
    const lines = report(args, graph)
    process.stdout.write(lines.length === 0 ? '' : lines.join('\n') + '\n')
  } catch (error) {
    if (error instanceof UserError) {
      process.stderr.write(`error: ${error.message}\n`)
      process.exit(error.code)
    }
    throw error
  }
}
